import Foundation
import XCTest
@testable import FrankenTermKit

/// PUBLIC SYNTHETIC TEST KEYS; NEVER AUTHORIZE. Certificates are independently
/// generated by OpenSSH; user-authentication signatures use pyca/cryptography.
struct UserCertificateFixtures: Decodable, Sendable {
    struct Certificate: Decodable, Sendable {
        let id: String, subjectAlgorithm: String, privatePEM: String, publicKey: String
        let certificate: String, authorityPublicKey: String, authenticationAlgorithm: String
        let signedData: String, signature: String
        var publicBlob: Data { UserCertificateFixtures.blob(publicKey) }
        var certificateBlob: Data { UserCertificateFixtures.blob(certificate) }
    }
    let user: String, sessionIdentifierHex: String, certificates: [Certificate]
    let largeCertificate: Certificate
    let unicodeCertificate: String, wildcardCertificate: String, restrictedCertificate: String
    let withoutPTYCertificate: String, withoutForwardingCertificate: String, hostCertificate: String
    static let now = Date(timeIntervalSince1970: 1_793_059_200)
    static func blob(_ line: String) -> Data { Data(base64Encoded: line.split(separator: " ")[1].description)! }
    static func load() throws -> Self {
        var root = URL(fileURLWithPath: #filePath)
        for _ in 0..<6 { root.deleteLastPathComponent() }
        return try JSONDecoder().decode(Self.self,
            from: Data(contentsOf: root.appendingPathComponent("fixtures/ios-airgap/ssh-user-certificates.json")))
    }
}

final class SSHUserCertificateTests: XCTestCase {
    func testIndependentOpenSSHSubjectsAndAuthoritySignaturesAcrossAllSupportedFamilies() throws {
        let fixtures = try UserCertificateFixtures.load()
        XCTAssertEqual(fixtures.certificates.count, 6)
        for fixture in fixtures.certificates + [fixtures.largeCertificate] {
            let certificate = try SSHUserCertificate(blob: fixture.certificateBlob)
            XCTAssertEqual(certificate.subject, try SSHPublicIdentity(blob: fixture.publicBlob), fixture.id)
            XCTAssertEqual(certificate.subject.algorithm, fixture.subjectAlgorithm)
            XCTAssertEqual(certificate.authority.blob, UserCertificateFixtures.blob(fixture.authorityPublicKey))
            XCTAssertEqual(certificate.principals, [fixtures.user])
            XCTAssertEqual(certificate.validAfter, 1_577_836_800)
            XCTAssertEqual(certificate.validBefore, 2_524_608_000)
            XCTAssertNoThrow(try certificate.validateAuthentication(user: fixtures.user, now: UserCertificateFixtures.now,
                                                                   requiresPTY: true, requiresPortForwarding: true))
        }
    }

    func testValidityBoundariesAndExpiredImportRemainDistinct() throws {
        let fixture = try XCTUnwrap(UserCertificateFixtures.load().certificates.first)
        let certificate = try SSHUserCertificate(blob: fixture.certificateBlob)
        XCTAssertThrowsError(try certificate.validateAuthentication(user: "operator", now: Date(timeIntervalSince1970: Double(certificate.validAfter) - 1)))
        XCTAssertNoThrow(try certificate.validateAuthentication(user: "operator", now: Date(timeIntervalSince1970: Double(certificate.validAfter))))
        XCTAssertNoThrow(try certificate.validateAuthentication(user: "operator", now: Date(timeIntervalSince1970: Double(certificate.validBefore) - 0.5)))
        XCTAssertThrowsError(try certificate.validateAuthentication(user: "operator", now: Date(timeIntervalSince1970: Double(certificate.validBefore))))
        // Re-reading public material does not erase an expired credential or
        // alter the certificate. Only a new authentication is time gated.
        XCTAssertEqual(try SSHUserCertificate(blob: certificate.blob), certificate)
        XCTAssertNoThrow(try certificate.validateRestrictions(user: "operator", requiresPTY: true, requiresPortForwarding: true))
        for seconds in [Double.infinity, -Double.infinity, Double.nan, -1, Double(UInt64.max)] {
            XCTAssertThrowsError(try certificate.validateAuthentication(user: "operator", now: Date(timeIntervalSince1970: seconds)))
        }
    }

    func testPrincipalsUseExactSSHBytesAndOnlyEmptyListsAreWildcards() throws {
        let fixtures = try UserCertificateFixtures.load()
        let exact = try SSHUserCertificate(blob: UserCertificateFixtures.blob(fixtures.unicodeCertificate))
        XCTAssertNoThrow(try exact.validateAuthentication(user: "e\u{301}", now: UserCertificateFixtures.now))
        XCTAssertThrowsError(try exact.validateAuthentication(user: "\u{e9}", now: UserCertificateFixtures.now))
        XCTAssertThrowsError(try exact.validateAuthentication(user: "operator", now: UserCertificateFixtures.now))
        let wildcard = try SSHUserCertificate(blob: UserCertificateFixtures.blob(fixtures.wildcardCertificate))
        XCTAssertTrue(wildcard.principals.isEmpty)
        XCTAssertNoThrow(try wildcard.validateAuthentication(user: "operator", now: UserCertificateFixtures.now))
        XCTAssertNoThrow(try wildcard.validateAuthentication(user: "another-account", now: UserCertificateFixtures.now))
    }

    func testCriticalRestrictionsAndPTYForwardingPermissionsCannotBeDiscarded() throws {
        let fixtures = try UserCertificateFixtures.load()
        let restricted = try SSHUserCertificate(blob: UserCertificateFixtures.blob(fixtures.restrictedCertificate))
        XCTAssertEqual(Set(restricted.criticalOptions.keys), ["force-command"])
        XCTAssertThrowsError(try restricted.validateAuthentication(user: fixtures.user, now: UserCertificateFixtures.now))
        let noPTY = try SSHUserCertificate(blob: UserCertificateFixtures.blob(fixtures.withoutPTYCertificate))
        XCTAssertNoThrow(try noPTY.validateAuthentication(user: fixtures.user, now: UserCertificateFixtures.now))
        XCTAssertThrowsError(try noPTY.validateAuthentication(user: fixtures.user, now: UserCertificateFixtures.now, requiresPTY: true))
        let noForwarding = try SSHUserCertificate(blob: UserCertificateFixtures.blob(fixtures.withoutForwardingCertificate))
        XCTAssertNoThrow(try noForwarding.validateAuthentication(user: fixtures.user, now: UserCertificateFixtures.now, requiresPTY: true))
        XCTAssertThrowsError(try noForwarding.validateAuthentication(user: fixtures.user, now: UserCertificateFixtures.now, requiresPortForwarding: true))
        XCTAssertThrowsError(try SSHUserCertificate(blob: UserCertificateFixtures.blob(fixtures.hostCertificate)))
    }

    func testTamperedSignedContentsSignaturesAndFramingAreRejected() throws {
        let fixtures = try UserCertificateFixtures.load()
        for fixture in fixtures.certificates + [fixtures.largeCertificate] {
            let blob = fixture.certificateBlob
            var reader = ByteCursor(blob)
            _ = try reader.sshString()
            var nonceTampered = blob
            nonceTampered[reader.offset + 4] ^= 1
            var signatureTampered = blob
            signatureTampered[signatureTampered.count - 1] ^= 1
            for invalid in [nonceTampered, signatureTampered, Data(blob.dropLast()), blob + Data([0])] {
                XCTAssertThrowsError(try SSHUserCertificate(blob: invalid), fixture.id)
            }
        }
        XCTAssertThrowsError(try SSHUserCertificate(blob: Data(repeating: 0, count: SSHUserCertificate.maximumBlobBytes + 1)))
        XCTAssertThrowsError(try SSHUserCertificate(blob: fixtures.certificates[0].publicBlob))
    }

    func testCertificateChallengeMatchesIndependentOpenSSHRequestBytesAndRawIdentity() throws {
        let fixtures = try UserCertificateFixtures.load()
        for fixture in fixtures.certificates + [fixtures.largeCertificate] {
            let challenge = try SSHUserAuthenticationChallenge(sessionIdentifier: Data(0..<32), user: fixtures.user,
                publicBlob: fixture.certificateBlob, signatureAlgorithm: fixture.authenticationAlgorithm)
            XCTAssertEqual(challenge.signedData, try XCTUnwrap(Data(base64Encoded: fixture.signedData)), fixture.id)
            XCTAssertEqual(challenge.subjectPublicBlob, fixture.publicBlob)
            XCTAssertEqual(challenge.publicKeyAlgorithm, fixture.subjectAlgorithm)
            XCTAssertEqual(challenge.fingerprint, try SSHPublicIdentity(blob: fixture.publicBlob).fingerprint)
            XCTAssertEqual(challenge.authenticationAlgorithm, fixture.authenticationAlgorithm)
            XCTAssertFalse(challenge.algorithm.contains("-cert-"))
            XCTAssertLessThanOrEqual(challenge.signedData.count, SSHUserAuthenticationChallenge.maximumSignedDataBytes)
            XCTAssertThrowsError(try SSHUserAuthenticationChallenge(sessionIdentifier: Data(0..<32), user: "wrong-account",
                publicBlob: fixture.certificateBlob, signatureAlgorithm: fixture.authenticationAlgorithm))
            XCTAssertThrowsError(try SSHUserAuthenticationChallenge(sessionIdentifier: Data(0..<32), user: fixtures.user,
                publicBlob: fixture.certificateBlob, signatureAlgorithm: fixture.subjectAlgorithm))
        }
    }
}
